.desk {
      position: relative;
      height: 30rem;
      border: 1px dashed var(--is-border);
      border-radius: var(--is-radius);
      overflow: hidden;
      background:
        linear-gradient(180deg,
          color-mix(in srgb, var(--is-accent) 6%, transparent) 0%,
          transparent 40%),
        repeating-linear-gradient(45deg,
          color-mix(in srgb, var(--is-text) 4%, transparent) 0 8px,
          transparent 8px 16px);
    }
    .desk note { position: absolute; pointer-events: none; color: var(--is-text-soft); font-size: .85rem; padding: 1rem; }

